using Jellyfin.Plugin.WatchlistTracker.Models; using Jellyfin.Plugin.WatchlistTracker.Services; using MediaBrowser.Controller.Events.Session; using MediaBrowser.Controller.Library;
namespace Jellyfin.Plugin.WatchlistTracker.Events;
public sealed class PlaybackEventHandler { readonly WatchlistService s; public PlaybackEventHandler(WatchlistService service,ILibraryManager library)=>s=service; public async Task OnItemPlayed(object? sender,ItemPlaybackStoppedEventArgs e){if(!Plugin.Instance.Configuration.AutoTrack||e.Item is not MediaBrowser.Controller.Entities.TV.Episode ep)return;long p=e.PlaybackPositionTicks??0,r=ep.RunTimeTicks??0;if(r==0||p*100<r*Plugin.Instance.Configuration.MinimumPlayPercentage)return;await s.AddOrUpdateAsync(new WatchedEpisode{JellyfinItemId=ep.Id,SeriesName=ep.SeriesName??"Unbekannte Serie",SeasonNumber=ep.ParentIndexNumber??0,EpisodeNumber=ep.IndexNumber??0,EpisodeName=ep.Name??"",Overview=ep.Overview,WatchedAt=DateTime.UtcNow,PlaybackPositionTicks=p,RunTimeTicks=r});}}
